        unitPrice: 8500,
        vatRate: 21,
        discountPercent: 5,
      },
    ],
  };
  const totals = invoiceTotals(invoice);
  const lineDisc = Math.round(42500 * 5 / 100);
  const amountAfterDiscount = 42500 - lineDisc;
  const vat = Math.round(amountAfterDiscount * 0.21);
